/* menu */
#menu{position:fixed;inset:0;z-index:145;background:var(--bg);display:flex;flex-direction:column;justify-content:center;padding:0 var(--edge);clip-path:inset(0 0 100% 0);transition:clip-path .8s cubic-bezier(.76,0,.24,1)}
body.mo #menu{clip-path:inset(0 0 0 0)}
#menu ol{list-style:none;counter-reset:m}
#menu li{counter-increment:m;border-top:1px solid var(--line)}
#menu li:last-child{border-bottom:1px solid var(--line)}
#menu a{display:flex;align-items:baseline;gap:20px;padding:clamp(12px,2vw,22px) 0;font-family:var(--serif);font-weight:300;font-size:clamp(30px,6.4vw,68px);line-height:1.04;color:var(--mut);transition:color .35s,padding-left .4s}
#menu a::before{content:counter(m,decimal-leading-zero);font-family:var(--mono);font-size:12px;color:var(--dim);font-weight:400;align-self:center}
#menu a:hover{color:var(--ink);padding-left:16px}
#menu .mfoot{margin-top:40px;display:flex;flex-wrap:wrap;gap:14px 34px;font-family:var(--mono);font-size:11px;letter-spacing:.12em;color:var(--mut)}
#menu .mfoot a:hover{color:var(--bronze)}

/* layout */
section{position:relative}
.wrap{width:min(1380px,100% - var(--edge)*2);margin:0 auto}
.eyebrow{font-family:var(--mono);font-size:11px;letter-spacing:.26em;text-transform:uppercase;color:var(--mut);display:flex;align-items:center;gap:14px}
.eyebrow .n{color:var(--bronze)}
.eyebrow .ln{width:42px;height:1px;background:var(--line2)}
.sec-head{margin-bottom:clamp(46px,6vw,84px);display:grid;grid-template-columns:1fr;gap:26px}
.sec-head .row{display:flex;justify-content:space-between;align-items:flex-end;gap:30px;flex-wrap:wrap}
.sec-title{font-family:var(--serif);font-weight:300;font-size:clamp(34px,5.6vw,76px);line-height:1.02;letter-spacing:-.015em;max-width:16ch}
.sec-title em{font-style:italic;color:var(--bronze)}
.sec-note{font-family:var(--sans);color:var(--mut);max-width:380px;font-size:15px;line-height:1.65}

/* mask reveal */
.lm{display:block;overflow:hidden;padding-bottom:.06em}
.lmi{display:block;transform:translateY(112%)}
.rv{opacity:0;transform:translateY(26px)}

/* ghost numeral */
.ghost{position:absolute;top:clamp(40px,7vw,90px);right:var(--edge);font-family:var(--serif);font-weight:300;font-size:clamp(150px,24vw,360px);line-height:.8;color:transparent;-webkit-text-stroke:1px rgba(233,228,216,.06);pointer-events:none;user-select:none;z-index:0}

/* links */
.ulink{font-family:var(--mono);font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--ink);display:inline-flex;align-items:center;gap:12px;position:relative;padding-bottom:5px}
.ulink .u{position:absolute;left:0;bottom:0;width:100%;height:1px;background:var(--line2)}
.ulink .u::after{content:'';position:absolute;left:0;top:0;width:0;height:1px;background:var(--bronze);transition:width .45s cubic-bezier(.76,0,.24,1)}
.ulink:hover .u::after{width:100%}
.ulink .ar{transition:transform .4s}
.ulink:hover .ar{transform:translateX(5px)}

/* ===== HERO / DOSSIER ===== */
#top{padding-top:var(--hd);min-height:100vh;display:flex;flex-direction:column;justify-content:center}
.filestrip{display:flex;justify-content:space-between;gap:24px;flex-wrap:wrap;padding:22px 0;border-bottom:1px solid var(--line);font-family:var(--mono);font-size:10px;letter-spacing:.2em;text-transform:uppercase;color:var(--dim)}
.filestrip b{color:var(--mut);font-weight:400}
.filestrip .st{color:var(--ox);display:flex;align-items:center;gap:8px}
.filestrip .st i{width:5px;height:5px;border-radius:50%;background:var(--ox);animation:blink 2s infinite}
.hero-grid{display:grid;grid-template-columns:1.55fr .85fr;gap:clamp(30px,5vw,80px);padding:clamp(46px,7vw,96px) 0;align-items:end}
.hero-ey{margin-bottom:30px}
.hero-name{font-family:var(--serif);font-weight:300;line-height:.88;letter-spacing:-.02em}
.hero-name .l1{font-size:clamp(58px,11vw,164px);font-style:italic}
.hero-name .l2{font-size:clamp(58px,11vw,164px);font-weight:500}
.hero-stmt{margin-top:34px;font-family:var(--serif);font-weight:300;font-style:italic;font-size:clamp(18px,2vw,26px);line-height:1.4;color:var(--mut);max-width:30ch}
.hero-stmt em{font-style:normal;color:var(--ink)}
.hero-cta{margin-top:40px;display:flex;gap:38px;flex-wrap:wrap}
.record{border-top:1px solid var(--line)}
.record .rt{font-family:var(--mono);font-size:10px;letter-spacing:.24em;text-transform:uppercase;color:var(--dim);padding:18px 0 8px}
.record .rr{display:flex;justify-content:space-between;align-items:baseline;gap:18px;padding:14px 0;border-bottom:1px solid var(--line)}
.record .rr .k{font-family:var(--mono);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--mut)}
.record .rr .v{font-family:var(--serif);font-weight:400;font-size:21px;color:var(--ink)}
.record .rr .v.b{color:var(--bronze)}
.record .rnote{margin-top:16px;font-family:var(--mono);font-size:10px;letter-spacing:.1em;color:var(--dim);line-height:1.7}
.hero-foot{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:24px 0 30px;border-top:1px solid var(--line)}
.scroll{font-family:var(--mono);font-size:10px;letter-spacing:.24em;text-transform:uppercase;color:var(--mut);display:flex;align-items:center;gap:14px}
.scroll .bar{width:1px;height:42px;background:var(--line2);position:relative;overflow:hidden}
.scroll .bar::after{content:'';position:absolute;top:-50%;left:0;width:100%;height:50%;background:var(--bronze);animation:drop 2s infinite}
@keyframes drop{0%{top:-50%}100%{top:100%}}
.hero-foot .coord{font-family:var(--mono);font-size:10px;letter-spacing:.2em;color:var(--dim);text-transform:uppercase}

/* marquee */
.marq{border-top:1px solid var(--line);border-bottom:1px solid var(--line);overflow:hidden;padding:22px 0;background:var(--bg2)}
.marq-t{display:flex;gap:54px;white-space:nowrap;width:max-content;animation:tick 64s linear infinite}
.marq:hover .marq-t{animation-play-state:paused}
.marq-t span{font-family:var(--serif);font-weight:300;font-style:italic;font-size:clamp(18px,2.4vw,30px);color:var(--mut);display:flex;align-items:center;gap:54px}
.marq-t span b{color:var(--ink);font-style:normal;font-weight:400}
.marq-t span i{color:var(--bronze);font-style:normal}
@keyframes tick{to{transform:translateX(-50%)}}

/* ===== PROFILE ===== */
#profile{padding:clamp(96px,13vw,180px) 0}
.prof-grid{display:grid;grid-template-columns:.92fr 1.08fr;gap:clamp(34px,5.5vw,90px);align-items:start}
.fig{position:relative}
.wipe{position:relative;overflow:hidden;aspect-ratio:4/5;background:var(--panel)}
.wipe img{width:100%;height:100%;object-fit:cover;will-change:transform}
.fig .cap{margin-top:14px;font-family:var(--mono);font-size:10px;letter-spacing:.2em;text-transform:uppercase;color:var(--dim)}
.pull{font-family:var(--serif);font-weight:300;font-size:clamp(24px,3vw,40px);line-height:1.22;letter-spacing:-.01em}
.pull em{font-style:italic;color:var(--bronze)}
.prof-text p{color:var(--mut);line-height:1.72;margin-top:24px;font-size:15.5px;max-width:46ch}
.cap-list{margin-top:38px;border-top:1px solid var(--line)}
.cap{display:flex;justify-content:space-between;align-items:center;gap:24px;padding:15px 0;border-bottom:1px solid var(--line);transition:padding-left .4s}
.cap:hover{padding-left:12px}
.cap .cl{font-family:var(--sans);font-size:14px;letter-spacing:.01em;color:var(--ink)}
.cap .cv{font-family:var(--mono);font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--dim)}
.cap:hover .cv{color:var(--bronze)}
.ledger{margin-top:clamp(64px,9vw,120px);display:grid;grid-template-columns:repeat(6,1fr);border-top:1px solid var(--line)}
.ledger .c{padding:30px 22px 28px;border-right:1px solid var(--line)}
.ledger .c:last-child{border-right:0}
.ledger .c .num{font-family:var(--serif);font-weight:400;font-size:clamp(30px,3.6vw,52px);line-height:1;color:var(--ink)}
.ledger .c .num.b{color:var(--bronze)}
.ledger .c .lab{margin-top:14px;font-family:var(--mono);font-size:9.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--mut);line-height:1.5}

/* ===== RECORD ===== */
#record{padding:clamp(96px,13vw,180px) 0;overflow:hidden}
.rec{display:grid;grid-template-columns:200px 1fr 230px;gap:clamp(24px,4vw,64px);padding:clamp(34px,4.5vw,60px) 0;border-top:1px solid var(--line);position:relative;transition:background .4s}
.rec:last-child{border-bottom:1px solid var(--line)}
.rec::before{content:'';position:absolute;inset:0;background:rgba(233,228,216,.018);opacity:0;transition:opacity .4s;pointer-events:none}
.rec:hover::before{opacity:1}
.rec .meta{font-family:var(--mono);font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--dim);line-height:1.9}
.rec .meta .idx{color:var(--bronze);font-size:12px;letter-spacing:.2em;display:block;margin-bottom:10px}
.rec .body{position:relative;z-index:1}
.rec .role{font-family:var(--serif);font-weight:400;font-size:clamp(22px,2.8vw,36px);line-height:1.08;letter-spacing:-.01em;transition:transform .4s}
.rec:hover .role{transform:translateX(8px)}
.rec .co{font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--bronze);margin-top:12px}
.rec .sum{font-family:var(--serif);font-style:italic;font-weight:300;font-size:16px;color:var(--mut);margin-top:16px;line-height:1.5;max-width:48ch}
.rec ul{list-style:none;margin-top:22px;display:grid;gap:11px}
.rec li{position:relative;padding-left:20px;color:var(--mut);line-height:1.6;font-size:14px}
.rec li::before{content:'';position:absolute;left:0;top:9px;width:7px;height:1px;background:var(--bronze)}
.rec li b{color:var(--ink);font-weight:500}
.rec .mets{position:relative;z-index:1}
.rec .mets .mt{display:flex;justify-content:space-between;gap:14px;padding:9px 0;border-bottom:1px solid var(--line);font-family:var(--mono);font-size:10px;letter-spacing:.1em;text-transform:uppercase}
.rec .mets .mt:last-child{border-bottom:0}
.rec .mets .mt .mk{color:var(--dim)}
.rec .mets .mt .mv{color:var(--ink)}
.rec .mets .mt .mv.b{color:var(--bronze)}
@media(max-width:1000px){.rec{grid-template-columns:1fr;gap:22px}.rec .mets{display:flex;flex-wrap:wrap;gap:0 26px}.rec .mets .mt{border-bottom:0;padding:4px 0}}

/* ===== WORK ===== */
#work{padding:clamp(96px,13vw,180px) 0}
.proj{display:grid;grid-template-columns:1.05fr .95fr;gap:clamp(30px,5vw,84px);align-items:center;padding:clamp(44px,5.5vw,80px) 0;border-top:1px solid var(--line)}
.proj:last-child{border-bottom:1px solid var(--line)}
.proj:nth-child(even){grid-template-columns:.95fr 1.05fr}
.proj:nth-child(even) .pmedia{order:2}
.pmedia{position:relative;overflow:hidden;aspect-ratio:16/11;background:var(--panel)}
.pmedia img{width:100%;height:100%;object-fit:cover;will-change:transform;transition:transform 1.2s cubic-bezier(.2,.7,.2,1)}
.pmedia:hover img{transform:scale(1.05)}
.pmedia .pn{position:absolute;top:16px;left:16px;font-family:var(--mono);font-size:10px;letter-spacing:.2em;color:var(--ink);background:rgba(11,11,12,.7);padding:6px 10px;border:1px solid var(--line)}
.pinfo .ptag{font-family:var(--mono);font-size:10px;letter-spacing:.22em;text-transform:uppercase;color:var(--ox)}
.pinfo h3{font-family:var(--serif);font-weight:400;font-size:clamp(26px,3.6vw,46px);line-height:1.02;letter-spacing:-.01em;margin:16px 0 18px}
.pinfo p{color:var(--mut);line-height:1.7;font-size:15px;max-width:46ch}
.pinfo .pmets{margin:26px 0;display:flex;flex-wrap:wrap;gap:30px}
.pinfo .pmets .pm .pv{font-family:var(--serif);font-weight:400;font-size:26px;color:var(--ink);line-height:1}
.pinfo .pmets .pm.b .pv{color:var(--bronze)}
.pinfo .pmets .pm .pl{font-family:var(--mono);font-size:9.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--dim);margin-top:7px}
.pinfo .stack{font-family:var(--mono);font-size:10.5px;letter-spacing:.08em;color:var(--mut);line-height:1.8;margin-bottom:24px}
.pinfo .stack b{color:var(--dim);font-weight:400}

/* ===== PROTOCOLS ===== */
#protocols{padding:clamp(96px,13vw,180px) 0;overflow:hidden}
.proto-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:clamp(34px,5vw,90px)}
.proto-list{border-top:1px solid var(--line)}
.prow{display:flex;align-items:center;gap:20px;padding:clamp(15px,1.9vw,24px) 4px;border-bottom:1px solid var(--line);cursor:none;transition:padding-left .4s}
.prow .pn{font-family:var(--mono);font-size:11px;color:var(--dim);letter-spacing:.1em;transition:color .3s}
.prow .pt{font-family:var(--serif);font-weight:300;font-size:clamp(17px,2.1vw,27px);color:var(--mut);transition:color .3s}
.prow .ar{margin-left:auto;font-family:var(--mono);color:var(--dim);transition:transform .35s,color .3s}
.prow:hover,.prow.act{padding-left:16px}
.prow:hover .pt,.prow.act .pt{color:var(--ink)}
.prow.act .pn{color:var(--bronze)}
.prow.act .ar{color:var(--bronze);transform:translateX(6px)}
.pdet{position:sticky;top:calc(var(--hd) + 40px);align-self:start;border:1px solid var(--line);padding:clamp(30px,3.4vw,48px);background:var(--bg2)}
.pdet .pdn{font-family:var(--mono);font-size:10px;letter-spacing:.24em;text-transform:uppercase;color:var(--bronze)}
.pdet .pdt{font-family:var(--serif);font-weight:400;font-size:clamp(24px,3vw,38px);line-height:1.06;margin:18px 0 22px;letter-spacing:-.01em}
.pdet .pdd{color:var(--mut);line-height:1.72;font-size:15px}
.pdet .pda{margin-top:26px;padding-top:20px;border-top:1px solid var(--line);font-family:var(--mono);font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--dim)}
.pdet .pda b{color:var(--bronze);font-weight:400}
.writing{margin-top:clamp(80px,10vw,140px)}
.wgrid{display:grid;grid-template-columns:1fr 1fr;gap:0 70px;margin-top:34px}
.wgrid a{display:flex;gap:18px;align-items:baseline;padding:15px 0;border-bottom:1px solid var(--line);color:var(--mut);transition:color .35s,padding-left .35s}
.wgrid a .wn{font-family:var(--mono);font-size:10px;color:var(--dim)}
.wgrid a .wt{font-size:14px;line-height:1.45}
.wgrid a:hover{color:var(--ink);padding-left:8px}
.wgrid a:hover .wn{color:var(--bronze)}

/* ===== SIGNAL ===== */
#signal{position:relative;min-height:92vh;display:flex;align-items:center;overflow:hidden;border-top:1px solid var(--line)}
.sig-bg{position:absolute;inset:0;z-index:0}
.sig-bg img{width:100%;height:130%;object-fit:cover;object-position:center;will-change:transform;opacity:.5}
.sig-bg .ov{position:absolute;inset:0;background:linear-gradient(90deg,var(--bg) 0%,rgba(11,11,12,.82) 42%,rgba(11,11,12,.4) 100%)}
.sig-in{position:relative;z-index:2;padding:clamp(96px,12vw,150px) 0}
.sig-in .era{font-family:var(--serif);font-weight:300;font-size:clamp(40px,7.4vw,104px);line-height:.92;letter-spacing:-.02em;margin-top:24px}
.sig-in .era em{font-style:italic;color:var(--bronze)}
.sig-in p{max-width:48ch;color:var(--mut);line-height:1.72;margin:28px 0 34px;font-size:16px}
.sig-stats{display:flex;flex-wrap:wrap;gap:42px;margin-bottom:38px}
.sig-stats .ss .n{font-family:var(--serif);font-weight:400;font-size:clamp(28px,3.6vw,46px);color:var(--ink)}
.sig-stats .ss .l{font-family:var(--mono);font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:var(--mut);margin-top:6px}
.sig-links{display:flex;flex-wrap:wrap;gap:30px}

/* ===== CONTACT ===== */
#contact{padding:clamp(96px,13vw,180px) 0 0;overflow:hidden}
.cq{font-family:var(--serif);font-weight:300;font-size:clamp(30px,5.4vw,72px);line-height:1.05;letter-spacing:-.015em;max-width:15ch}
.cq em{font-style:italic;color:var(--bronze)}
.csub{margin-top:30px;max-width:600px;color:var(--mut);line-height:1.72;font-size:16px}
.cmail{display:inline-block;margin-top:48px;font-family:var(--serif);font-weight:300;font-size:clamp(24px,5.4vw,68px);line-height:1.05;letter-spacing:-.015em;color:var(--ink);position:relative;padding-bottom:.08em;word-break:break-word}
.cmail .u{position:absolute;left:0;bottom:0;width:100%;height:1px;background:var(--line2)}
.cmail .u::after{content:'';position:absolute;left:0;top:0;width:0;height:1px;background:var(--bronze);transition:width .6s cubic-bezier(.76,0,.24,1)}
.cmail:hover .u::after{width:100%}
.cgrid{margin-top:clamp(56px,7vw,96px);display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--line)}
.cgrid .cg{padding:26px 24px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);display:flex;flex-direction:column;gap:9px;transition:background .35s}
.cgrid .cg:nth-child(3n){border-right:0}
.cgrid .cg:hover{background:var(--panel)}
.cgrid .cg .ck{font-family:var(--mono);font-size:9.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--dim)}
.cgrid .cg .cv{font-family:var(--sans);font-size:15px;color:var(--ink);transition:color .35s}
.cgrid .cg:hover .cv{color:var(--bronze)}
.roles{margin-top:clamp(46px,6vw,80px);font-family:var(--mono);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--mut);line-height:2.2}
.roles b{color:var(--dim);font-weight:400}
.avail{margin-top:30px;display:inline-flex;align-items:center;gap:13px;font-family:var(--mono);font-size:10.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--bronze)}
.avail i{width:7px;height:7px;border-radius:50%;background:var(--bronze);box-shadow:0 0 8px rgba(185,154,111,.7);animation:blink 1.8s infinite}

footer{margin-top:clamp(80px,10vw,140px);border-top:1px solid var(--line);padding:34px 0}
footer .wrap{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;font-family:var(--mono);font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--dim)}
footer .wrap b{color:var(--mut);font-weight:400}

@media(max-width:1000px){
  .hero-grid{grid-template-columns:1fr;align-items:start}
  .prof-grid{grid-template-columns:1fr}
  .ledger{grid-template-columns:repeat(3,1fr)}
  .ledger .c:nth-child(3n){border-right:0}
  .proj,.proj:nth-child(even){grid-template-columns:1fr}
  .proj:nth-child(even) .pmedia{order:0}
  .proto-grid{grid-template-columns:1fr}
  .pdet{position:static}
  .wgrid{grid-template-columns:1fr}
  .cgrid{grid-template-columns:1fr}
  .cgrid .cg{border-right:0}
  .hero-foot .coord{display:none}
}
@media(max-width:560px){
  .ledger{grid-template-columns:repeat(2,1fr)}
  .ledger .c:nth-child(3n){border-right:1px solid var(--line)}
  .ledger .c:nth-child(2n){border-right:0}
  .sig-stats{gap:26px}
}
</style>
</head>
