  <ul class="nav">
    <li><a href="#profile" data-scroll><sup>01</sup>Profile</a></li>
    <li><a href="#record" data-scroll><sup>02</sup>Record</a></li>
    <li><a href="#work" data-scroll><sup>03</sup>Work</a></li>
