<script src="https://cdn.jsdelivr.net/npm/lenis@1.1.14/dist/lenis.min.js"></script>
<script>
(function(){
  "use strict";
  gsap.registerPlugin(ScrollTrigger);
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* cursor */
  var cd = document.getElementById('cd'), cr = document.getElementById('cr');
  if (window.matchMedia('(hover:hover)').matches){
    var cx = gsap.quickTo(cd,'x',{duration:.1,ease:'power3.out'});
    var cy = gsap.quickTo(cd,'y',{duration:.1,ease:'power3.out'});
    var rx = gsap.quickTo(cr,'x',{duration:.45,ease:'power3.out'});
    var ry = gsap.quickTo(cr,'y',{duration:.45,ease:'power3.out'});
    window.addEventListener('mousemove', function(e){ cx(e.clientX); cy(e.clientY); rx(e.clientX); ry(e.clientY); });
    document.addEventListener('mouseover', function(e){ if(e.target.closest('a,button,.hov')) cr.classList.add('on'); });
    document.addEventListener('mouseout', function(e){ if(e.target.closest('a,button,.hov')) cr.classList.remove('on'); });
  }

  /* lenis */
  var lenis = null;
  if (!reduced && window.Lenis){
    lenis = new Lenis({ duration:1.2, smoothWheel:true, lerp:0.085 });
    lenis.on('scroll', ScrollTrigger.update);
    gsap.ticker.add(function(t){ lenis.raf(t*1000); });
    gsap.ticker.lagSmoothing(0);
  }

  /* header + progress */
  var hd = document.getElementById('hd');
  window.addEventListener('scroll', function(){ hd.classList.toggle('scrolled', window.scrollY > 40); }, {passive:true});
  gsap.to('#prog', { scaleX:1, ease:'none', scrollTrigger:{ trigger:'body', start:'top top', end:'bottom bottom', scrub:.3 }});

  /* menu */
  var burger = document.getElementById('burger');
  function closeMenu(){ document.body.classList.remove('mo'); }
  burger.addEventListener('click', function(){ document.body.classList.toggle('mo'); });

  /* smooth scroll */
  document.querySelectorAll('[data-scroll]').forEach(function(a){
    a.addEventListener('click', function(e){
      var sel = a.getAttribute('href');
      if (!sel || sel.charAt(0) !== '#') return;
      var t = document.querySelector(sel);
      if (!t) return;
      e.preventDefault(); closeMenu();
      if (lenis) lenis.scrollTo(t, { offset:0, duration:1.5 });
      else t.scrollIntoView({behavior:'smooth'});
    });
  });

  /* active nav */
  var navLinks = document.querySelectorAll('.nav a');
  var map = {profile:0, record:1, work:2, protocols:3, contact:4};
  Object.keys(map).forEach(function(id){
    var link = navLinks[map[id]]; if(!link) return;
    ScrollTrigger.create({ trigger:'#'+id, start:'top 55%', end:'bottom 45%',
      onToggle:function(self){ link.classList.toggle('act', self.isActive); } });
  });

  /* reveals */
  gsap.utils.toArray('.rv').forEach(function(el){
    gsap.to(el, { y:0, opacity:1, duration:1.1, ease:'power3.out', scrollTrigger:{ trigger:el, start:'top 88%' }});
  });
  gsap.utils.toArray('.lm').forEach(function(el){
    var inner = el.querySelector('.lmi');
    gsap.to(inner, { yPercent:0, duration:1.2, ease:'power4.out', scrollTrigger:{ trigger:el, start:'top 90%' }});
  });

  /* image wipes + parallax */
  gsap.utils.toArray('.wipe, .pmedia').forEach(function(w){
    var img = w.querySelector('img'); if(!img) return;
    gsap.fromTo(w, { clipPath:'inset(100% 0 0 0)' }, { clipPath:'inset(0% 0 0 0)', duration:1.4, ease:'power4.inOut', scrollTrigger:{ trigger:w, start:'top 84%' }});
    gsap.fromTo(img, { scale:1.16 }, { scale:1.04, duration:1.7, ease:'power3.out', scrollTrigger:{ trigger:w, start:'top 84%' }});
    gsap.fromTo(img, { yPercent:-7 }, { yPercent:7, ease:'none', scrollTrigger:{ trigger:w, start:'top bottom', end:'bottom top', scrub:true }});
  });
  /* signal bg parallax */
  var sigImg = document.getElementById('sigImg');
  if (sigImg) gsap.fromTo(sigImg, { yPercent:-12 }, { yPercent:12, ease:'none', scrollTrigger:{ trigger:'#signal', start:'top bottom', end:'bottom top', scrub:true }});

  /* ghost parallax */
  gsap.utils.toArray('.ghost').forEach(function(g){
    gsap.fromTo(g, { yPercent:0 }, { yPercent:-18, ease:'none', scrollTrigger:{ trigger:g.parentElement, start:'top bottom', end:'bottom top', scrub:true }});
  });

  /* counters */
  document.querySelectorAll('[data-count]').forEach(function(el){
    var target = parseFloat(el.getAttribute('data-count'));
    var dec = el.getAttribute('data-dec') ? parseInt(el.getAttribute('data-dec'),10) : 0;
    var suffix = el.getAttribute('data-suffix') || '';
    var obj = { v:0 };
    ScrollTrigger.create({ trigger:el, start:'top 92%', once:true, onEnter:function(){
      gsap.to(obj, { v:target, duration:2.1, ease:'power3.out', onUpdate:function(){
        el.textContent = obj.v.toLocaleString('en-US',{minimumFractionDigits:dec,maximumFractionDigits:dec}) + suffix;
      }});
    }});
  });

  /* protocols */
  var rows = Array.prototype.slice.call(document.querySelectorAll('.prow'));
  var pdn = document.getElementById('pdn'), pdt = document.getElementById('pdt'), pdd = document.getElementById('pdd'), pda = document.getElementById('pda');
  var detail = document.getElementById('protoDetail');
  function setProto(i){
    rows.forEach(function(r,j){ r.classList.toggle('act', i===j); });
    var r = rows[i];
    gsap.to(detail, { opacity:0, y:12, duration:.16, onComplete:function(){
      pdn.textContent = 'PROTOCOL ' + r.querySelector('.pn').textContent;
      pdt.textContent = r.getAttribute('data-t');
      pdd.textContent = r.getAttribute('data-d');
      pda.innerHTML = r.getAttribute('data-a');
      gsap.to(detail, { opacity:1, y:0, duration:.34, ease:'power2.out' });
    }});
  }
  rows.forEach(function(r,i){
    r.addEventListener('mouseenter', function(){ setProto(i); });
    r.addEventListener('click', function(){ setProto(i); });
  });

  /* preloader + intro */
  function startIntro(){
    document.documentElement.classList.remove('loading');
    if (reduced){
      gsap.set('.rv', { opacity:1, y:0 });
      gsap.set('.lmi', { yPercent:0 });
      ScrollTrigger.refresh();
      return;
    }
    var tl = gsap.timeline();
    tl.to('.filestrip', { opacity:1, y:0, duration:.7, ease:'power3.out' })
      .to('.hero-ey', { opacity:1, y:0, duration:.7, ease:'power3.out' }, '-=.4')
      .to('.hero-name .lmi', { yPercent:0, duration:1.1, ease:'power4.out', stagger:.12 }, '-=.3')
      .to('.hero-stmt', { opacity:1, y:0, duration:.7, ease:'power3.out' }, '-=.5')
      .to('.hero-cta', { opacity:1, y:0, duration:.7, ease:'power3.out' }, '-=.45')
      .to('.record', { opacity:1, y:0, duration:.8, ease:'power3.out' }, '-=.6')
      .to('.hero-foot', { opacity:1, duration:.6 }, '-=.4');
    gsap.set(['.filestrip','.hero-ey','.hero-stmt','.hero-cta','.record','.hero-foot'], { opacity:0, y:20 });
    ScrollTrigger.refresh();
  }

  function runPre(){
    var pct = document.getElementById('pct'), line = document.getElementById('pline');
    var obj = { v:0 };
    gsap.to(obj, { v:100, duration:1.5, ease:'power2.inOut', onUpdate:function(){
      var v = Math.floor(obj.v);
      pct.textContent = String(v).padStart(3,'0');
      line.style.transform = 'scaleX(' + (obj.v/100) + ')';
    }, onComplete:function(){
      gsap.timeline()
        .to('#pre .pmid, #pre .ptop, #pre .pbot', { opacity:0, duration:.3 })
        .to('#pre', { yPercent:-100, duration:1, ease:'power4.inOut', onComplete:function(){
          var p = document.getElementById('pre'); if(p) p.remove();
          startIntro();
        }});
    }});
  }

  if (reduced){
    var p = document.getElementById('pre'); if(p) p.remove();
    startIntro();
  } else {
    runPre();
  }

  window.addEventListener('load', function(){ ScrollTrigger.refresh(); });
})();
</script>
</body>
</html>
