  background:repeating-linear-gradient(to bottom,rgba(0,0,0,0) 0,rgba(0,0,0,0) 2px,rgba(0,0,0,.18) 3px,rgba(0,0,0,0) 4px)}
.vignette{position:fixed;inset:0;z-index:59;pointer-events:none;background:radial-gradient(120% 90% at 50% 30%,transparent 55%,rgba(0,0,0,.7) 100%)}
#progress{position:fixed;top:0;left:0;width:3px;height:100vh;z-index:120;background:linear-gradient(var(--cyan),var(--red));transform-origin:top;transform:scaleY(0)}

/* ---------- cursor ---------- */
#cursor-dot,#cursor-ring{position:fixed;top:0;left:0;z-index:200;pointer-events:none;border-radius:50%;transform:translate(-50%,-50%)}
#cursor-dot{width:6px;height:6px;background:var(--cyan);mix-blend-mode:difference}
#cursor-ring{width:38px;height:38px;border:1px solid rgba(92,242,230,.55);transition:width .25s,height .25s,background .25s,border-color .25s}
#cursor-ring.hot{width:64px;height:64px;background:rgba(92,242,230,.08);border-color:var(--cyan)}
@media (hover:none){#cursor-dot,#cursor-ring{display:none}}

/* ---------- boot ---------- */
#boot{position:fixed;inset:0;z-index:300;background:var(--void);display:flex;flex-direction:column;justify-content:space-between;padding:clamp(22px,4vw,54px);font-family:var(--mono)}
#boot .boot-top{display:flex;justify-content:space-between;align-items:flex-start;gap:20px}
#boot .boot-mark{font-family:var(--display);font-weight:800;letter-spacing:.04em;font-size:clamp(13px,1.4vw,16px)}
#boot .boot-mark b{color:var(--cyan)}
#boot .boot-tag{color:var(--mut2);font-size:11px;letter-spacing:.3em;text-transform:uppercase;text-align:right}
#bootlog{font-size:clamp(11px,1.25vw,14px);line-height:1.9;color:var(--mut);max-width:760px}
#bootlog .bl{opacity:0;transform:translateY(6px);animation:blin .35s forwards}
#bootlog .bl b{color:var(--cyan)}
#bootlog .bl.r b{color:var(--red)}
@keyframes blin{to{opacity:1;transform:none}}
#boot .boot-bot{display:flex;justify-content:space-between;align-items:flex-end}
#boot .boot-hint{color:var(--mut2);font-size:11px;letter-spacing:.2em}
#bootpct{font-family:var(--display);font-weight:800;font-size:clamp(48px,12vw,150px);line-height:.8;color:var(--ink)}
#bootpct span{color:var(--cyan)}
#boot .bar{position:absolute;left:0;bottom:0;height:2px;width:0;background:var(--cyan);transition:width .12s linear}

/* ---------- nav ---------- */
#nav{position:fixed;top:0;left:0;width:100%;height:var(--nav-h);z-index:150;display:flex;align-items:center;justify-content:space-between;padding:0 clamp(18px,3.4vw,46px);transition:background .4s,border-color .4s,backdrop-filter .4s;border-bottom:1px solid transparent}
#nav.scrolled{background:rgba(5,5,7,.72);backdrop-filter:blur(14px);border-bottom:1px solid var(--line)}
.nav-logo{font-family:var(--display);font-weight:800;font-size:18px;letter-spacing:.02em;display:flex;align-items:center;gap:9px}
.nav-logo .dot{width:9px;height:9px;background:var(--cyan);box-shadow:0 0 12px var(--cyan);animation:blink 2.4s infinite}
@keyframes blink{0%,92%,100%{opacity:1}96%{opacity:.2}}
.nav-links{display:flex;gap:clamp(14px,1.8vw,30px);list-style:none}
.nav-links a{font-family:var(--mono);font-size:11.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--mut);position:relative;padding:6px 0;transition:color .3s}
.nav-links a::before{content:attr(data-n);color:var(--mut2);margin-right:7px;font-size:9px;vertical-align:top}
.nav-links a::after{content:'';position:absolute;left:0;bottom:0;width:0;height:1px;background:var(--cyan);transition:width .35s}
.nav-links a:hover,.nav-links a.active{color:var(--ink)}
.nav-links a.active::after,.nav-links a:hover::after{width:100%}
.nav-right{display:flex;align-items:center;gap:18px}
.nav-status{font-family:var(--mono);font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--cyan);border:1px solid rgba(92,242,230,.4);padding:7px 12px;display:flex;align-items:center;gap:8px}
.nav-status i{width:6px;height:6px;border-radius:50%;background:var(--cyan);box-shadow:0 0 8px var(--cyan);animation:blink 1.8s infinite}
.burger{display:none;width:42px;height:42px;border:1px solid var(--line2);background:transparent;position:relative;cursor:none}
.burger span{position:absolute;left:11px;right:11px;height:1.5px;background:var(--ink);transition:.35s}
.burger span:nth-child(1){top:15px}
.burger span:nth-child(2){top:20px}
.burger span:nth-child(3){top:25px}
body.menu-open .burger span:nth-child(1){top:20px;transform:rotate(45deg)}
body.menu-open .burger span:nth-child(2){opacity:0}
body.menu-open .burger span:nth-child(3){top:20px;transform:rotate(-45deg)}
@media(max-width:980px){.nav-links{display:none}.burger{display:block}.nav-status{display:none}}

/* ---------- menu overlay ---------- */
#menu{position:fixed;inset:0;z-index:140;background:rgba(5,5,7,.97);backdrop-filter:blur(8px);display:flex;flex-direction:column;justify-content:center;padding:0 clamp(24px,7vw,120px);transform:translateY(-100%);transition:transform .7s cubic-bezier(.76,0,.24,1)}
body.menu-open #menu{transform:none}
#menu ol{list-style:none;counter-reset:m}
#menu li{counter-increment:m;border-top:1px solid var(--line)}
#menu li:last-child{border-bottom:1px solid var(--line)}
#menu a{display:flex;align-items:baseline;gap:18px;padding:clamp(10px,1.6vw,18px) 0;font-family:var(--display);font-weight:700;font-size:clamp(28px,6vw,64px);line-height:1.05;color:var(--mut);transition:color .3s,padding-left .3s}
#menu a::before{content:counter(m,decimal-leading-zero);font-family:var(--mono);font-size:13px;color:var(--mut2);font-weight:400;align-self:center}
#menu a:hover{color:var(--ink);padding-left:14px}
#menu .menu-foot{margin-top:34px;display:flex;flex-wrap:wrap;gap:14px 30px;font-family:var(--mono);font-size:12px;color:var(--mut)}
#menu .menu-foot a:hover{color:var(--cyan)}

/* ---------- shared ---------- */
section{position:relative}
.wrap{width:min(1440px,92vw);margin:0 auto}
.sec-head{display:flex;align-items:flex-end;justify-content:space-between;gap:30px;flex-wrap:wrap;margin-bottom:clamp(34px,5vw,70px)}
.sec-tag{font-family:var(--mono);font-size:12px;letter-spacing:.28em;text-transform:uppercase;color:var(--mut);display:flex;align-items:center;gap:12px}
.sec-tag .n{color:var(--cyan)}
.sec-tag .bar{width:46px;height:1px;background:var(--line2)}
.sec-title{font-family:var(--display);font-weight:800;font-size:clamp(30px,5.4vw,68px);line-height:.96;letter-spacing:-.01em;margin-top:18px}
.sec-title .stroke{-webkit-text-stroke:1.4px var(--ink);color:transparent}
.sec-sub{font-family:var(--body);color:var(--mut);max-width:430px;font-size:15px;line-height:1.6}
.eyebrow{font-family:var(--mono);font-size:12px;letter-spacing:.26em;text-transform:uppercase;color:var(--cyan)}

/* corner frame */
.frame{position:relative}
.frame::before,.frame::after{content:'';position:absolute;width:14px;height:14px;border:1px solid var(--cyan);opacity:.6}
.frame::before{top:-1px;left:-1px;border-right:0;border-bottom:0}
.frame::after{bottom:-1px;right:-1px;border-left:0;border-top:0}

/* buttons */
.btn{display:inline-flex;align-items:center;gap:10px;font-family:var(--mono);font-size:12px;letter-spacing:.16em;text-transform:uppercase;padding:14px 22px;border:1px solid var(--line2);color:var(--ink);position:relative;overflow:hidden;transition:color .35s,border-color .35s;cursor:none}
.btn::before{content:'';position:absolute;inset:0;background:var(--cyan);transform:translateY(101%);transition:transform .4s cubic-bezier(.76,0,.24,1);z-index:-1}
.btn:hover{color:var(--void);border-color:var(--cyan)}
.btn:hover::before{transform:none}
.btn.red::before{background:var(--red)}
.btn.red:hover{border-color:var(--red)}
.btn .ar{transition:transform .35s}
.btn:hover .ar{transform:translateX(4px)}

/* chips */
.chips{display:flex;flex-wrap:wrap;gap:8px}
.chip{font-family:var(--mono);font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--mut);border:1px solid var(--line);padding:5px 10px;background:rgba(255,255,255,.02)}
.chip.cy{color:var(--cyan);border-color:rgba(92,242,230,.3)}

/* ---------- hero ---------- */
#hero{min-height:100vh;display:flex;align-items:center;padding:calc(var(--nav-h) + 30px) 0 0;overflow:hidden}
#net{position:absolute;inset:0;width:100%;height:100%;z-index:0}
.hero-grid{position:absolute;inset:0;z-index:1;opacity:.5;pointer-events:none;
  background-image:linear-gradient(var(--line) 1px,transparent 1px),linear-gradient(90deg,var(--line) 1px,transparent 1px);
  background-size:64px 64px;mask-image:radial-gradient(120% 80% at 30% 40%,#000 30%,transparent 80%)}
.hero-inner{position:relative;z-index:3;width:min(1440px,92vw);margin:0 auto;display:grid;grid-template-columns:1.55fr .9fr;gap:40px;align-items:center}
.hero-eyebrow{display:flex;align-items:center;gap:14px;font-family:var(--mono);font-size:12px;letter-spacing:.24em;text-transform:uppercase;color:var(--mut);margin-bottom:26px}
.hero-eyebrow .pulse{width:8px;height:8px;border-radius:50%;background:var(--cyan);box-shadow:0 0 10px var(--cyan);animation:blink 1.6s infinite}
.hero-name{font-family:var(--display);font-weight:800;line-height:.86;letter-spacing:-.02em}
.hero-name .ln{display:block;overflow:hidden}
.hero-name .ln1{font-size:clamp(40px,8.6vw,118px)}
.hero-name .ln2{font-size:clamp(40px,8.6vw,118px);-webkit-text-stroke:1.6px var(--ink);color:transparent}
.hero-name .ch{display:inline-block;will-change:transform}
.hero-name .sp{display:inline-block;width:.32em}
.hero-role{margin-top:22px;font-family:var(--mono);font-size:clamp(13px,1.5vw,18px);letter-spacing:.06em;color:var(--cyan);display:flex;align-items:center;gap:12px}
.hero-role .pre{color:var(--mut2)}
.role-mask{overflow:hidden;height:1.25em;display:inline-flex}
#role{display:inline-block;will-change:transform}
.hero-lede{margin-top:26px;max-width:520px;color:var(--mut);font-size:clamp(15px,1.4vw,18px);line-height:1.6}
.hero-cta{margin-top:34px;display:flex;flex-wrap:wrap;gap:14px}
.hero-hud{font-family:var(--mono);font-size:12px;line-height:2.05;color:var(--mut);border:1px solid var(--line);padding:24px 26px;background:rgba(8,8,12,.5);backdrop-filter:blur(4px);position:relative}
.hero-hud .hud-t{font-family:var(--display);font-size:11px;letter-spacing:.2em;color:var(--ink);margin-bottom:14px;text-transform:uppercase}
.hero-hud .row{display:flex;justify-content:space-between;gap:18px;border-bottom:1px dashed var(--line);padding:2px 0}
.hero-hud .row:last-child{border-bottom:0}
.hero-hud .k{color:var(--mut2)}
.hero-hud .v{color:var(--ink);text-align:right}
.hero-hud .v.cy{color:var(--cyan)}
.hero-hud .v.gd{color:var(--gold)}
.hero-foot{position:absolute;left:0;bottom:26px;width:100%;z-index:3}
.hero-foot .wrap{display:flex;align-items:center;justify-content:space-between;gap:20px}
.scroll-cue{font-family:var(--mono);font-size:11px;letter-spacing:.22em;text-transform:uppercase;color:var(--mut);display:flex;align-items:center;gap:12px}
.scroll-cue .line{width:1px;height:46px;background:linear-gradient(var(--cyan),transparent);position:relative;overflow:hidden}
.scroll-cue .line::after{content:'';position:absolute;top:-50%;left:0;width:100%;height:50%;background:var(--cyan);animation:drop 1.8s infinite}
@keyframes drop{0%{top:-50%}100%{top:100%}}
.hero-coords{font-family:var(--mono);font-size:11px;letter-spacing:.18em;color:var(--mut2)}

/* ticker */
.ticker{border-top:1px solid var(--line);border-bottom:1px solid var(--line);overflow:hidden;background:var(--void2);padding:16px 0}
.ticker-track{display:flex;gap:48px;white-space:nowrap;width:max-content;animation:tick 38s linear infinite}
.ticker:hover .ticker-track{animation-play-state:paused}
.ticker-track span{font-family:var(--display);font-weight:600;font-size:clamp(15px,2vw,26px);letter-spacing:.02em;color:var(--mut);display:flex;align-items:center;gap:48px}
.ticker-track span b{color:var(--ink)}
.ticker-track span i{color:var(--cyan);font-style:normal}
@keyframes tick{to{transform:translateX(-50%)}}

/* ---------- about / centaur ---------- */
#centaur{padding:clamp(90px,12vw,170px) 0}
.about-grid{display:grid;grid-template-columns:1fr 1.05fr;gap:clamp(30px,5vw,80px);align-items:center}
.about-media{position:relative;aspect-ratio:4/5;overflow:hidden;border:1px solid var(--line)}
.about-media img{width:100%;height:120%;object-fit:cover;will-change:transform;filter:contrast(1.05) saturate(1.05)}
.about-media .ov{position:absolute;inset:0;background:linear-gradient(transparent 40%,rgba(5,5,7,.85));z-index:2}
.about-media .tag{position:absolute;left:18px;bottom:18px;z-index:3;font-family:var(--mono);font-size:11px;letter-spacing:.2em;color:var(--cyan);text-transform:uppercase}
.about-text .quote{font-family:var(--display);font-weight:600;font-size:clamp(20px,2.6vw,32px);line-height:1.25;margin:22px 0}
.about-text .quote em{font-style:normal;color:var(--cyan)}
.about-text p{color:var(--mut);line-height:1.7;margin-bottom:16px;font-size:15.5px}
.cap-list{margin-top:26px;border-top:1px solid var(--line)}
.cap-list .cap{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:13px 0;border-bottom:1px solid var(--line);font-family:var(--mono);font-size:12.5px;letter-spacing:.04em}
.cap-list .cap .cl{color:var(--ink)}
.cap-list .cap .cv{color:var(--mut2);text-transform:uppercase;letter-spacing:.12em;font-size:11px}
.cap-list .cap:hover .cl{color:var(--cyan)}

/* counters strip */
.counters{margin-top:clamp(60px,8vw,110px);display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--line)}
.counters .c{padding:30px 22px;border-right:1px solid var(--line);border-bottom:1px solid var(--line)}
.counters .c:nth-child(4n){border-right:0}
.counters .c .num{font-family:var(--display);font-weight:800;font-size:clamp(30px,4vw,52px);line-height:1;color:var(--ink)}
.counters .c .num.cy{color:var(--cyan)}
.counters .c .num.gd{color:var(--gold)}
.counters .c .num.rd{color:var(--red)}
.counters .c .lab{margin-top:12px;font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--mut)}

/* ---------- experience ---------- */
#ops{padding:clamp(90px,12vw,170px) 0;overflow:hidden}
.xp-wrap{position:relative;padding-left:clamp(20px,4vw,60px)}
.xp-line{position:absolute;left:6px;top:8px;bottom:8px;width:1px;background:var(--line2);transform-origin:top}
.xp-line::after{content:'';position:absolute;inset:0;background:linear-gradient(var(--cyan),var(--red));transform:scaleY(0);transform-origin:top}
.xp{position:relative;padding:clamp(26px,3.4vw,44px) 0 clamp(26px,3.4vw,44px) clamp(28px,4vw,56px);border-bottom:1px solid var(--line)}
.xp:last-child{border-bottom:0}
.xp::before{content:'';position:absolute;left:-2px;top:clamp(34px,4vw,52px);width:13px;height:13px;border:1px solid var(--cyan);background:var(--void);transform:rotate(45deg);transition:background .3s,box-shadow .3s}
.xp:hover::before{background:var(--cyan);box-shadow:0 0 16px var(--cyan)}
.xp-top{display:flex;justify-content:space-between;gap:24px;flex-wrap:wrap;align-items:flex-start}
.xp-idx{font-family:var(--mono);font-size:12px;color:var(--mut2);letter-spacing:.2em}
.xp-rank{font-family:var(--mono);font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--gold);border:1px solid rgba(242,180,65,.4);padding:5px 10px}
.xp h3{font-family:var(--display);font-weight:700;font-size:clamp(20px,2.8vw,34px);line-height:1.08;margin:14px 0 8px;letter-spacing:-.01em}
.xp-co{font-family:var(--mono);font-size:13px;letter-spacing:.06em;color:var(--cyan);text-transform:uppercase}
.xp-period{font-family:var(--mono);font-size:11.5px;letter-spacing:.1em;color:var(--mut2);margin-top:6px;text-transform:uppercase}
.xp-points{list-style:none;margin:22px 0 0;display:grid;gap:12px}
.xp-points li{position:relative;padding-left:22px;color:var(--mut);line-height:1.6;font-size:14.5px}
.xp-points li::before{content:'▹';position:absolute;left:0;top:0;color:var(--cyan)}
.xp-points li b{color:var(--ink);font-weight:600}
.xp-metrics{margin-top:22px;display:flex;flex-wrap:wrap;gap:10px}
.xp-metrics .m{font-family:var(--mono);font-size:11px;letter-spacing:.08em;color:var(--ink);background:rgba(92,242,230,.06);border:1px solid rgba(92,242,230,.22);padding:7px 12px}
.xp-metrics .m b{color:var(--cyan)}
.xp-tags{margin-top:16px}
.xp .xp-side{position:absolute;right:0;top:clamp(26px,3.4vw,44px);width:120px;opacity:.5}
.xp .xp-side img{width:100%;border:1px solid var(--line);filter:grayscale(.2) contrast(1.1)}
@media(max-width:1100px){.xp .xp-side{display:none}}

/* ---------- arsenal (horizontal) ---------- */
#arsenal{height:100vh;overflow:hidden;background:var(--void2);border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.gal-track{display:flex;align-items:center;height:100%;gap:clamp(20px,3vw,46px);padding:0 6vw;will-change:transform}
.gal-panel{flex:0 0 auto;width:min(70vw,560px);display:flex;flex-direction:column;gap:18px}
.gal-panel.intro{width:min(78vw,520px);padding-right:30px}
.gal-panel.intro .sec-tag{margin-bottom:18px}
.gal-panel.intro h2{font-family:var(--display);font-weight:800;font-size:clamp(34px,6vw,72px);line-height:.94}
.gal-panel.intro p{color:var(--mut);line-height:1.65;margin-top:18px;max-width:420px}
.gal-panel.intro .hint{margin-top:26px;font-family:var(--mono);font-size:11px;letter-spacing:.2em;color:var(--cyan);text-transform:uppercase;display:flex;align-items:center;gap:10px}
.gal-media{position:relative;aspect-ratio:5/4;overflow:hidden;border:1px solid var(--line);background:var(--void)}
.gal-media img{width:100%;height:100%;object-fit:cover;transition:transform .8s cubic-bezier(.2,.7,.2,1)}
.gal-panel:hover .gal-media img{transform:scale(1.06)}
.gal-media .gn{position:absolute;top:14px;left:14px;font-family:var(--display);font-weight:800;font-size:13px;color:var(--void);background:var(--cyan);padding:4px 9px;letter-spacing:.1em}
.gal-body .gt{font-family:var(--display);font-weight:700;font-size:clamp(20px,2.4vw,30px)}
.gal-body .gd{color:var(--mut);font-size:13.5px;line-height:1.55;margin-top:6px}
.gal-body .chips{margin-top:12px}

/* ---------- projects ---------- */
#projects{padding:clamp(90px,12vw,170px) 0}
.proj{display:grid;grid-template-columns:1.05fr 1fr;gap:clamp(28px,4.5vw,70px);align-items:center;padding:clamp(40px,5vw,72px) 0;border-bottom:1px solid var(--line)}
.proj:nth-child(even){grid-template-columns:1fr 1.05fr}
.proj:nth-child(even) .proj-media{order:2}
.proj:last-child{border-bottom:0}
.proj-media{position:relative;aspect-ratio:16/11;overflow:hidden;border:1px solid var(--line);will-change:transform}
.proj-media img{width:100%;height:100%;object-fit:cover}
.proj-media .scan{position:absolute;inset:0;background:linear-gradient(115deg,transparent 40%,rgba(92,242,230,.12) 50%,transparent 60%);transform:translateX(-100%);transition:transform .9s}
.proj-media:hover .scan{transform:translateX(100%)}
.proj-media .pidx{position:absolute;top:14px;left:14px;font-family:var(--mono);font-size:11px;letter-spacing:.2em;color:var(--cyan);background:rgba(5,5,7,.7);padding:5px 9px;border:1px solid rgba(92,242,230,.3)}
.proj-info .ptag{font-family:var(--mono);font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:var(--red)}
.proj-info h3{font-family:var(--display);font-weight:700;font-size:clamp(24px,3.4vw,44px);line-height:1;margin:14px 0 16px;letter-spacing:-.01em}
.proj-info p{color:var(--mut);line-height:1.7;font-size:15px;max-width:520px}
.proj-metrics{margin:22px 0;display:flex;flex-wrap:wrap;gap:18px}
.proj-metrics .pm{font-family:var(--mono);font-size:12px;color:var(--mut)}
.proj-metrics .pm b{display:block;font-family:var(--display);font-weight:700;font-size:22px;color:var(--ink);margin-bottom:3px}
.proj-metrics .pm.cy b{color:var(--cyan)}
.proj-metrics .pm.gd b{color:var(--gold)}
.proj-info .chips{margin-bottom:22px}

/* ---------- protocols ---------- */
#protocols{padding:clamp(90px,12vw,170px) 0;overflow:hidden}
.proto-bg{position:absolute;right:-6%;top:8%;width:min(46vw,560px);opacity:.16;z-index:0;pointer-events:none}
.proto-bg img{width:100%}
.proto-grid{position:relative;z-index:2;display:grid;grid-template-columns:1.1fr .9fr;gap:clamp(30px,5vw,80px)}
.proto-list{border-top:1px solid var(--line)}
.proto-row{display:flex;align-items:center;gap:18px;padding:clamp(14px,1.8vw,22px) 6px;border-bottom:1px solid var(--line);cursor:none;transition:padding-left .35s}
.proto-row .pn{font-family:var(--mono);font-size:12px;color:var(--mut2);letter-spacing:.1em}
.proto-row .pt{font-family:var(--display);font-weight:600;font-size:clamp(16px,2vw,26px);color:var(--mut);transition:color .3s}
.proto-row .ar{margin-left:auto;color:var(--mut2);transition:transform .35s,color .3s;font-family:var(--mono)}
.proto-row:hover,.proto-row.active{padding-left:18px}
.proto-row:hover .pt,.proto-row.active .pt{color:var(--ink)}
.proto-row.active .pn{color:var(--cyan)}
.proto-row.active .ar{color:var(--cyan);transform:translateX(6px)}
.proto-detail{position:sticky;top:calc(var(--nav-h) + 40px);align-self:start;border:1px solid var(--line);padding:clamp(26px,3vw,40px);background:rgba(8,8,12,.6)}
.proto-detail .pdn{font-family:var(--mono);font-size:12px;letter-spacing:.2em;color:var(--cyan)}
.proto-detail .pdt{font-family:var(--display);font-weight:700;font-size:clamp(22px,2.8vw,34px);line-height:1.05;margin:14px 0 18px}
.proto-detail .pdd{color:var(--mut);line-height:1.7;font-size:15px}
.proto-detail .pda{margin-top:22px;padding-top:18px;border-top:1px solid var(--line);font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--mut2)}
.proto-detail .pda b{color:var(--gold);font-weight:400}

/* writing */
.writing{margin-top:clamp(70px,9vw,120px)}
.write-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 60px;margin-top:30px}
.write-grid a{display:flex;gap:16px;align-items:baseline;padding:14px 0;border-bottom:1px solid var(--line);color:var(--mut);transition:color .3s,padding-left .3s}
.write-grid a .wn{font-family:var(--mono);font-size:11px;color:var(--mut2)}
.write-grid a .wt{font-size:14.5px;line-height:1.4}
.write-grid a:hover{color:var(--ink);padding-left:8px}
.write-grid a:hover .wn{color:var(--cyan)}

/* ---------- signal / music ---------- */
#signal{position:relative;min-height:100vh;display:flex;align-items:center;overflow:hidden;border-top:1px solid var(--line)}
.signal-bg{position:absolute;inset:0;z-index:0}
.signal-bg img{width:100%;height:130%;object-fit:cover;object-position:center 30%;will-change:transform;filter:contrast(1.1) saturate(1.1)}
.signal-bg .ov{position:absolute;inset:0;background:linear-gradient(90deg,rgba(5,5,7,.96) 0%,rgba(5,5,7,.7) 45%,rgba(5,5,7,.35) 100%)}
.signal-inner{position:relative;z-index:2;width:min(1440px,92vw);margin:0 auto;padding:clamp(90px,12vw,150px) 0}
.signal-inner .era{font-family:var(--display);font-weight:800;font-size:clamp(40px,8vw,104px);line-height:.9;letter-spacing:-.02em}
.signal-inner .era .stroke{-webkit-text-stroke:1.4px var(--ink);color:transparent}
.signal-inner .era b{color:var(--red)}
.signal-inner p{max-width:520px;color:var(--mut);line-height:1.7;margin:24px 0 30px;font-size:16px}
.signal-stats{display:flex;flex-wrap:wrap;gap:34px;margin-bottom:34px}
.signal-stats .ss .n{font-family:var(--display);font-weight:800;font-size:clamp(26px,3.4vw,42px);color:var(--cyan)}
.signal-stats .ss .l{font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--mut);margin-top:4px}
.signal-links{display:flex;flex-wrap:wrap;gap:12px}

/* ---------- contact ---------- */
#contact{padding:clamp(90px,12vw,170px) 0 0;position:relative;overflow:hidden}
.contact-quote{font-family:var(--display);font-weight:700;font-size:clamp(28px,5vw,64px);line-height:1.04;letter-spacing:-.01em;max-width:14ch}
.contact-quote em{font-style:normal;color:var(--cyan)}
.contact-sub{margin-top:28px;max-width:640px;color:var(--mut);line-height:1.7;font-size:16px}
.giant-mail{display:inline-block;margin-top:46px;font-family:var(--display);font-weight:800;font-size:clamp(22px,5.6vw,72px);line-height:1.05;letter-spacing:-.01em;color:var(--ink);background:linear-gradient(var(--cyan),var(--cyan)) left bottom/0% 100% no-repeat;padding:.06em .12em;transition:background-size .5s cubic-bezier(.76,0,.24,1),color .4s;word-break:break-word}
.giant-mail:hover{background-size:100% 100%;color:var(--void)}
.contact-grid{margin-top:clamp(50px,7vw,90px);display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--line);border:1px solid var(--line)}
.contact-grid .cg{background:var(--void);padding:26px 24px;display:flex;flex-direction:column;gap:8px;transition:background .3s}
.contact-grid .cg:hover{background:var(--panel)}
.contact-grid .cg .ck{font-family:var(--mono);font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--mut2)}
.contact-grid .cg .cv{font-family:var(--body);font-size:16px;color:var(--ink);transition:color .3s}
.contact-grid .cg:hover .cv{color:var(--cyan)}
.contact-grid .cg .cv.cy{color:var(--cyan)}
.contact-grid .cg .cv.gd{color:var(--gold)}
.avail{margin-top:clamp(40px,5vw,70px);display:inline-flex;align-items:center;gap:14px;font-family:var(--mono);font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:var(--cyan);border:1px solid rgba(92,242,230,.4);padding:14px 22px}
.avail i{width:8px;height:8px;border-radius:50%;background:var(--cyan);box-shadow:0 0 10px var(--cyan);animation:blink 1.6s infinite}

/* footer */
footer{margin-top:clamp(70px,9vw,120px);border-top:1px solid var(--line);padding:34px 0}
footer .wrap{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;font-family:var(--mono);font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--mut2)}
footer .wrap b{color:var(--mut)}

/* shards */
.shard{position:absolute;font-family:var(--mono);font-size:11px;letter-spacing:.18em;color:var(--mut2);text-transform:uppercase;z-index:2;pointer-events:none;white-space:nowrap}
.shard.cy{color:rgba(92,242,230,.5)}
.shard.rd{color:rgba(255,59,92,.5)}

/* reveal */
[data-reveal]{opacity:0;transform:translateY(40px)}

/* responsive */
@media(max-width:980px){
  .hero-inner{grid-template-columns:1fr}
  .hero-hud{order:3}
  .about-grid{grid-template-columns:1fr}
  .counters{grid-template-columns:repeat(2,1fr)}
  .counters .c:nth-child(4n){border-right:1px solid var(--line)}
  .counters .c:nth-child(2n){border-right:0}
  .proj,.proj:nth-child(even){grid-template-columns:1fr}
  .proj:nth-child(even) .proj-media{order:0}
  .proto-grid{grid-template-columns:1fr}
  .proto-detail{position:static}
  .write-grid{grid-template-columns:1fr}
  .contact-grid{grid-template-columns:1fr}
  .hero-foot .hero-coords{display:none}
}
@media(max-width:560px){
  .counters{grid-template-columns:1fr}
  .counters .c{border-right:0!important}
  .signal-stats{gap:22px}
}
</style>
</head>
