<script src="https://cdn.jsdelivr.net/npm/gsap@3.12.5/dist/gsap.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/gsap@3.12.5/dist/ScrollTrigger.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/lenis@1.1.14/dist/lenis.min.js"></script>
<script>
(function(){
  "use strict";
  gsap.registerPlugin(ScrollTrigger);
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* ---------- cursor ---------- */
  var dot = document.getElementById('cursor-dot');
  var ring = document.getElementById('cursor-ring');
  if (window.matchMedia('(hover:hover)').matches) {
    var dx = gsap.quickTo(dot,'x',{duration:.12,ease:'power3.out'});
    var dy = gsap.quickTo(dot,'y',{duration:.12,ease:'power3.out'});
    var rx = gsap.quickTo(ring,'x',{duration:.4,ease:'power3.out'});
    var ry = gsap.quickTo(ring,'y',{duration:.4,ease:'power3.out'});
    window.addEventListener('mousemove', function(e){ dx(e.clientX); dy(e.clientY); rx(e.clientX); ry(e.clientY); });
    document.addEventListener('mouseover', function(e){ if(e.target.closest('a,button,.hoverable')) ring.classList.add('hot'); });
    document.addEventListener('mouseout', function(e){ if(e.target.closest('a,button,.hoverable')) ring.classList.remove('hot'); });
  }

  /* ---------- lenis ---------- */
  var lenis = null;
  if (!reduced && window.Lenis) {
    lenis = new Lenis({ duration:1.15, smoothWheel:true, lerp:0.09 });
    lenis.on('scroll', ScrollTrigger.update);
    gsap.ticker.add(function(t){ lenis.raf(t*1000); });
    gsap.ticker.lagSmoothing(0);
  }

  /* ---------- nav scroll state + progress ---------- */
  var nav = document.getElementById('nav');
  window.addEventListener('scroll', function(){ nav.classList.toggle('scrolled', window.scrollY > 40); }, {passive:true});
  gsap.to('#progress', { scaleY:1, ease:'none', scrollTrigger:{ trigger:'body', start:'top top', end:'bottom bottom', scrub:.3 }});

  /* ---------- menu ---------- */
  var burger = document.getElementById('burger');
  function closeMenu(){ document.body.classList.remove('menu-open'); }
  burger.addEventListener('click', function(){ document.body.classList.toggle('menu-open'); });

  /* ---------- smooth scroll links ---------- */
  document.querySelectorAll('[data-scroll]').forEach(function(a){
    a.addEventListener('click', function(e){
      var sel = a.getAttribute('href');
      if (!sel || sel.charAt(0) !== '#') return;
      var t = document.querySelector(sel);
      if (!t) return;
      e.preventDefault();
      closeMenu();
      if (lenis) lenis.scrollTo(t, { offset:0, duration:1.4 });
      else t.scrollIntoView({behavior:'smooth'});
    });
  });

  /* ---------- active nav ---------- */
  var navMap = {centaur:0, ops:1, arsenal:2, projects:3, protocols:4, contact:5};
  Object.keys(navMap).forEach(function(id){
    var link = document.querySelectorAll('.nav-links a')[navMap[id]];
    if (!link) return;
    ScrollTrigger.create({ trigger:'#'+id, start:'top 55%', end:'bottom 45%',
      onToggle:function(self){ if(self.isActive) link.classList.add('active'); else link.classList.remove('active'); } });
  });

  /* ---------- text split ---------- */
  function splitChars(el){
    var txt = el.textContent; el.innerHTML = '';
    for (var i=0;i<txt.length;i++){
      var c = txt[i];
      var s = document.createElement('span');
      if (c === ' '){ s.className='sp'; s.innerHTML='&nbsp;'; }
      else { s.className='ch'; s.textContent=c; }
      el.appendChild(s);
    }
  }
  splitChars(document.getElementById('name1'));
  splitChars(document.getElementById('name2'));
  var allChars = document.querySelectorAll('.hero-name .ch, .hero-name .sp');
  gsap.set(allChars, { yPercent:120, opacity:0 });

  /* ---------- role cycler ---------- */
  var roles = ['AI SAFETY ENGINEER','CREATIVE TECHNOLOGIST','VOICE AI ARCHITECT','TRUST & SAFETY LEAD','FULL-STACK DEVELOPER','RECORDING ARTIST'];
  var ri = 0, roleEl = document.getElementById('role');
  function cycleRole(){
    gsap.timeline()
      .to(roleEl,{ yPercent:-120, duration:.4, ease:'power3.in', onComplete:function(){ ri=(ri+1)%roles.length; roleEl.textContent=roles[ri]; gsap.set(roleEl,{yPercent:120}); }})
