        dx=n.x-mx; dy=n.y-my; d2=dx*dx+dy*dy;
        if (d2<25600){ var d=Math.sqrt(d2)||1; var f=(160-d)/160*.55; n.x+=dx/d*f; n.y+=dy/d*f; }
        if (n.x<-20)n.x=W+20; if (n.x>W+20)n.x=-20;
        if (n.y<-20)n.y=H+20; if (n.y>H+20)n.y=-20;
