.tlink.rt:hover .ar{transform:translateX(4px)}

/* duotone figures */
.duo{position:relative;overflow:hidden;background:#0d0d0f;border:1px solid var(--line)}
.duo img{width:100%;height:100%;object-fit:cover;filter:grayscale(1) contrast(1.08) brightness(.8)}
.duo::after{content:'';position:absolute;inset:0;background:linear-gradient(165deg,rgba(194,168,120,.20),rgba(10,10,11,.42) 70%);pointer-events:none}
.duo::before{content:'';position:absolute;inset:10px;border:1px solid rgba(233,228,218,.10);z-index:2;pointer-events:none}
.figcap{font-family:var(--mono);font-size:10px;letter-spacing:.2em;text-transform:uppercase;color:var(--dim);margin-top:12px;display:flex;justify-content:space-between}

/* ============ COVER ============ */
#cover{min-height:100svh;display:flex;flex-direction:column;justify-content:space-between;padding:calc(var(--navh) + 24px) 0 0;overflow:hidden}
.ghost{position:absolute;top:4vh;right:-7vw;z-index:1;font-family:var(--serif);font-style:italic;font-weight:300;font-size:48vw;line-height:.8;color:transparent;-webkit-text-stroke:1px rgba(233,228,218,.055);user-select:none;pointer-events:none}
.cover-grid{display:grid;grid-template-columns:1fr 250px;gap:clamp(30px,5vw,80px);align-items:end;flex:1;padding-bottom:clamp(36px,5vh,64px)}
.eyebrow{font-family:var(--mono);font-size:10.5px;letter-spacing:.28em;text-transform:uppercase;color:var(--bronze);display:flex;align-items:center;gap:14px;margin-bottom:clamp(24px,3.4vh,40px)}
.eyebrow::before{content:'';width:34px;height:1px;background:var(--bronze)}
.roleline{font-family:var(--mono);font-size:11.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--dim);margin-bottom:18px}
.roleline .mask{display:inline-block;overflow:hidden;vertical-align:bottom;height:1.3em}
#role{display:inline-block;color:var(--mut);will-change:transform}
.name{font-family:var(--serif);font-weight:340;line-height:.9;letter-spacing:-.02em}
.name .l1{font-size:clamp(64px,12.4vw,178px);display:block}
.name .l2{font-size:clamp(64px,12.4vw,178px);display:block;font-style:italic;font-weight:300;padding-left:.9em}
.name .l2 i{font-style:italic;color:var(--bronze)}
.statement{margin-top:clamp(26px,3.6vh,42px);max-width:47ch;color:var(--mut);font-size:clamp(15px,1.35vw,17.5px);line-height:1.7}
.statement b{color:var(--bone);font-weight:500}
.cover-cta{margin-top:clamp(28px,4vh,46px);display:flex;gap:clamp(24px,3.4vw,52px);flex-wrap:wrap}
.rail{border-left:1px solid var(--line);padding-left:clamp(20px,2vw,30px);display:flex;flex-direction:column;gap:0;align-self:stretch;justify-content:flex-end}
.rail .ri{padding:13px 0;border-bottom:1px solid var(--line)}
.rail .ri:first-child{border-top:1px solid var(--line)}
.rail .rk{font-family:var(--mono);font-size:9.5px;letter-spacing:.24em;text-transform:uppercase;color:var(--dim);display:block;margin-bottom:4px}
.rail .rv{font-family:var(--serif);font-style:italic;font-size:16.5px;color:var(--bone)}
.rail .rv.bz{color:var(--bronze)}
.cover-bar{border-top:1px solid var(--line);padding:18px 0}
.cover-bar .wrap{display:flex;align-items:center;justify-content:space-between;gap:20px}
.scue{display:flex;align-items:center;gap:14px;font-family:var(--mono);font-size:10px;letter-spacing:.26em;text-transform:uppercase;color:var(--dim)}
.scue .stick{width:1px;height:38px;background:var(--line2);position:relative;overflow:hidden}
.scue .stick::after{content:'';position:absolute;left:0;top:-50%;width:100%;height:50%;background:var(--bronze);animation:drop 2s cubic-bezier(.76,0,.24,1) infinite}
@keyframes drop{0%{top:-50%}100%{top:100%}}
.coords{font-family:var(--mono);font-size:10px;letter-spacing:.22em;color:var(--dim);text-transform:uppercase}
@media(max-width:940px){
 .cover-grid{grid-template-columns:1fr;align-items:start}
 .rail{border-left:0;border-top:1px solid var(--line);padding-left:0;padding-top:8px;flex-direction:row;flex-wrap:wrap;gap:0 34px}
 .rail .ri{border:0;padding:10px 0}
 .name .l2{padding-left:.5em}
 .coords{display:none}
}

/* marquee */
.marq{border-top:1px solid var(--line);border-bottom:1px solid var(--line);overflow:hidden;padding:15px 0;background:var(--bg)}
.marq-track{display:flex;gap:0;white-space:nowrap;width:max-content;animation:marq 70s linear infinite}
.marq span{font-family:var(--mono);font-size:10.5px;letter-spacing:.3em;text-transform:uppercase;color:rgba(233,228,218,.38);padding-right:.6em}
.marq i{font-style:normal;color:var(--bronze);opacity:.7;padding:0 1.6em}
@keyframes marq{to{transform:translateX(-50%)}}

/* ============ SYSTEM ============ */
.sys-grid{display:grid;grid-template-columns:.85fr 1.15fr;gap:clamp(34px,5vw,90px);align-items:start}
.sys-fig .duo{aspect-ratio:4/5}
.sys-fig .duo img{height:118%}
.quote{font-family:var(--serif);font-style:italic;font-weight:300;font-size:clamp(22px,2.6vw,32px);line-height:1.35;margin-bottom:26px}
.quote em{color:var(--bronze)}
.sys-text p{color:var(--mut);line-height:1.75;margin-bottom:16px;max-width:62ch}
.sys-text p b{color:var(--bone);font-weight:500}
.caps{margin-top:34px;border-top:1px solid var(--line)}
.caps .cap{display:flex;justify-content:space-between;align-items:baseline;gap:20px;padding:13px 2px;border-bottom:1px solid var(--line);transition:padding-left .35s}
.caps .cap:hover{padding-left:12px}
.caps .ck{font-size:13.5px;color:var(--bone);font-weight:500;letter-spacing:.02em}
.caps .cv{font-family:var(--mono);font-size:10px;letter-spacing:.18em;text-transform:uppercase;color:var(--dim);transition:color .3s}
.caps .cap:hover .cv{color:var(--bronze)}
.counters{margin-top:clamp(64px,8vw,110px);display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);border:1px solid var(--line)}
.counters .cell{background:var(--bg);padding:clamp(22px,2.6vw,34px) clamp(18px,2vw,28px);transition:background .4s}
.counters .cell:hover{background:var(--bg2)}
.counters .num{font-family:var(--serif);font-weight:340;font-size:clamp(34px,4vw,56px);line-height:1;color:var(--bone)}
.counters .num.bz{color:var(--bronze)}
.counters .lab{margin-top:12px;font-family:var(--mono);font-size:9.5px;letter-spacing:.2em;text-transform:uppercase;color:var(--dim)}
@media(max-width:940px){.sys-grid{grid-template-columns:1fr}.counters{grid-template-columns:repeat(2,1fr)}}
@media(max-width:520px){.counters{grid-template-columns:1fr}}

/* ============ OPERATIONS ============ */
.op{display:grid;grid-template-columns:250px 1fr;gap:clamp(24px,4vw,70px);padding:clamp(38px,5vw,64px) 0;border-top:1px solid var(--line);position:relative}
.op:last-of-type{border-bottom:1px solid var(--line)}
.op::before{content:'';position:absolute;left:0;top:-1px;height:1px;width:0;background:var(--bronze);transition:width .8s cubic-bezier(.76,0,.24,1)}
.op:hover::before{width:100%}
.op-meta .oidx{font-family:var(--mono);font-size:10px;letter-spacing:.24em;color:var(--dim);display:block;margin-bottom:16px}
.op-meta .orank{font-family:var(--mono);font-size:9.5px;letter-spacing:.2em;text-transform:uppercase;color:var(--bronze);display:block;margin-bottom:14px}
.op-meta .oco{font-family:var(--mono);font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--mut);display:block;margin-bottom:6px}
.op-meta .oper{font-family:var(--mono);font-size:10px;letter-spacing:.14em;color:var(--dim);text-transform:uppercase}
.op h3{font-family:var(--serif);font-weight:340;font-size:clamp(26px,3.4vw,44px);line-height:1.05;letter-spacing:-.01em;margin-bottom:22px;transition:color .35s}
.op:hover h3 em{color:var(--bronze)}
.op h3 em{font-style:italic;font-weight:300;color:var(--mut);transition:color .35s}
.op ul{list-style:none;display:grid;gap:11px;max-width:70ch}
.op li{position:relative;padding-left:24px;color:var(--mut);line-height:1.65;font-size:14.5px}
.op li::before{content:'—';position:absolute;left:0;color:var(--bronze)}
.op li b{color:var(--bone);font-weight:500}
.opm{margin-top:24px;display:flex;flex-wrap:wrap;gap:10px 30px;font-family:var(--mono);font-size:11px;letter-spacing:.06em;color:var(--dim)}
.opm b{color:var(--bronze);font-weight:500;margin-right:7px}
@media(max-width:860px){.op{grid-template-columns:1fr;gap:22px}}

/* ============ ARSENAL (pinned horizontal) ============ */
#arsenal{height:100vh;overflow:hidden;border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:var(--bg2)}
.ars-track{display:flex;align-items:stretch;height:100%;will-change:transform}
.ars-p{flex:0 0 auto;width:min(72vw,560px);padding:0 clamp(28px,4vw,64px);border-right:1px solid var(--line);display:flex;flex-direction:column;justify-content:center;gap:22px;position:relative}
.ars-p.intro{width:min(84vw,620px);justify-content:center}
.ars-p .al{font-family:var(--serif);font-style:italic;font-weight:300;font-size:clamp(26px,2.6vw,36px);color:var(--bronze)}
.ars-p h3{font-family:var(--serif);font-weight:340;font-size:clamp(38px,5.2vw,74px);line-height:.98;letter-spacing:-.015em;transition:color .4s}
.ars-p:hover h3{color:var(--bronze)}
.ars-p p{color:var(--mut);font-size:14.5px;line-height:1.7;max-width:38ch}
.ars-p .stack{font-family:var(--mono);font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--dim);line-height:2}
.ars-p .stack i{font-style:normal;color:var(--bronze);opacity:.6;padding:0 .8em}
.ars-p .anum{position:absolute;top:clamp(24px,4vh,44px);left:clamp(28px,4vw,64px);font-family:var(--mono);font-size:10px;letter-spacing:.26em;color:var(--dim)}
.ars-hint{display:flex;align-items:center;gap:14px;font-family:var(--mono);font-size:10px;letter-spacing:.26em;text-transform:uppercase;color:var(--bronze)}
.ars-hint .arr{display:inline-block;animation:nudge 1.8s ease-in-out infinite}
@keyframes nudge{0%,100%{transform:translateX(0)}50%{transform:translateX(8px)}}

/* ============ WORK ============ */
.wrow{display:grid;grid-template-columns:70px 1fr auto;gap:clamp(18px,3vw,50px);align-items:center;padding:clamp(30px,3.6vw,48px) 6px;border-top:1px solid var(--line);transition:padding-left .45s cubic-bezier(.76,0,.24,1),background .45s}
.wrow:last-of-type{border-bottom:1px solid var(--line)}
.wrow:hover{padding-left:26px;background:rgba(233,228,218,.015)}
.wrow .wi{font-family:var(--mono);font-size:11px;letter-spacing:.2em;color:var(--dim);transition:color .35s}
.wrow:hover .wi{color:var(--bronze)}
.wrow h3{font-family:var(--serif);font-weight:340;font-size:clamp(26px,3.8vw,54px);line-height:1;letter-spacing:-.01em;transition:color .35s}
.wrow:hover h3{font-style:italic;color:var(--bronze)}
.wrow .wstack{margin-top:10px;font-family:var(--mono);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--dim)}
.wrow .wm{font-family:var(--mono);font-size:11px;letter-spacing:.08em;color:var(--mut);text-align:right;line-height:2}
.wrow .wm b{color:var(--bone);font-weight:500}
.wrow .wm b.bz{color:var(--bronze)}
.wrow .go{font-family:var(--serif);font-style:italic;font-size:22px;color:var(--dim);transition:transform .4s,color .4s;margin-left:clamp(14px,2vw,30px)}
.wrow:hover .go{transform:translateX(8px);color:var(--bronze)}
.wright{display:flex;align-items:center}
@media(max-width:860px){.wrow{grid-template-columns:1fr}.wright{justify-content:flex-start}.wrow .wm{text-align:left}.wrow .go{display:none}}
#preview{position:fixed;top:0;left:0;z-index:90;width:320px;aspect-ratio:4/3;pointer-events:none;opacity:0;transform:translate(-50%,-50%) scale(.9) rotate(-2deg);overflow:hidden;border:1px solid var(--line2)}
#preview img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0;filter:grayscale(1) contrast(1.08) brightness(.82);transition:opacity .3s}
#preview img.on{opacity:1}
#preview::after{content:'';position:absolute;inset:0;background:linear-gradient(165deg,rgba(194,168,120,.22),rgba(10,10,11,.4))}

/* ============ PROTOCOLS ============ */
.acc{border-top:1px solid var(--line)}
.acc:last-of-type{border-bottom:1px solid var(--line)}
.acc-h{width:100%;display:grid;grid-template-columns:64px 1fr 30px;align-items:center;gap:18px;padding:clamp(22px,2.8vw,32px) 4px;text-align:left;transition:padding-left .4s}
.acc-h:hover{padding-left:16px}
.acc-h .an{font-family:var(--mono);font-size:10.5px;letter-spacing:.22em;color:var(--dim);transition:color .35s}
.acc-h .at{font-family:var(--serif);font-weight:340;font-size:clamp(20px,2.6vw,32px);letter-spacing:-.01em;color:var(--mut);transition:color .35s,font-style .35s}
.acc.open .an,.acc-h:hover .an{color:var(--bronze)}
.acc.open .at,.acc-h:hover .at{color:var(--bone)}
.acc.open .at{font-style:italic;color:var(--bronze)}
.acc-x{position:relative;width:16px;height:16px;justify-self:end}
.acc-x::before,.acc-x::after{content:'';position:absolute;background:var(--mut);transition:transform .5s cubic-bezier(.76,0,.24,1),background .35s}
.acc-x::before{left:0;right:0;top:7px;height:1px}
.acc-x::after{top:0;bottom:0;left:7px;width:1px}
.acc.open .acc-x::after{transform:scaleY(0)}
.acc.open .acc-x::before{background:var(--bronze)}
.acc-b{height:0;overflow:hidden}
.acc-inner{padding:0 4px clamp(24px,3vw,36px) 82px;max-width:760px}
.acc-inner p{color:var(--mut);line-height:1.75;font-size:14.5px}
.acc-inner .ap{margin-top:16px;font-family:var(--mono);font-size:10px;letter-spacing:.22em;text-transform:uppercase;color:var(--dim)}
.acc-inner .ap b{color:var(--bronze);font-weight:400}
@media(max-width:700px){.acc-h{grid-template-columns:40px 1fr 24px}.acc-inner{padding-left:4px}}

/* writing */
.writing{margin-top:clamp(80px,10vw,140px)}
.wgrid{display:grid;grid-template-columns:1fr 1fr;gap:0 clamp(30px,5vw,80px);margin-top:26px}
.wgrid a{display:flex;gap:16px;align-items:baseline;padding:13px 2px;border-top:1px solid var(--line);color:var(--dim);font-size:14px;transition:color .35s,padding-left .35s}
.wgrid a .wn{font-family:var(--mono);font-size:10px;letter-spacing:.14em}
.wgrid a:hover{color:var(--bone);padding-left:10px}
.wgrid a:hover .wn{color:var(--bronze)}
@media(max-width:760px){.wgrid{grid-template-columns:1fr}}

/* ============ SIGNAL ============ */
